def prime_fib(n):
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def fibonacci_generator():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    fib_gen = fibonacci_generator()
    prime_fibs = []
    for fib in fib_gen:
        if is_prime(fib):
            prime_fibs.append(fib)
            if len(prime_fibs) == n:
                return prime_fibs[-1]

    return None
```

The approach is to generate Fibonacci numbers and check if they are prime. We use a generator to produce Fibonacci numbers and a helper function to check for primality. We keep track of the prime Fibonacci numbers and return the n-th one when we reach it.

